import React, { useState, useEffect } from 'react';
import { Container, Typography, Grid } from '@mui/material';
import TaskForm from './components/TaskForm';
import TaskList from './components/TaskList';
import CompletedTasks from './components/CompletedTasks';
import { getTasks, createTask, updateTask, deleteTask } from './api';


const App = () => {
  const [tasks, setTasks] = useState([]);

  // Load tasks from API
  useEffect(() => {
    const loadTasks = async () => {
      try {
        const fetchedTasks = await getTasks();
        setTasks(fetchedTasks);
      } catch (error) {
        console.error('Failed to load tasks:', error);
      }
    };

    loadTasks();
  }, []);

  // Add a task
  const addTask = async (task) => {
    try {
      const newTask = await createTask(task);
      setTasks([...tasks, newTask]);
    } catch (error) {
      console.error('Failed to add task:', error);
    }
  };

  // Update a task
  const updateTaskHandler = async (id, updatedTask) => {
    try {
      const updated = await updateTask(id, updatedTask);
      setTasks(tasks.map(task => (task.id === id ? updated : task)));
    } catch (error) {
      console.error('Failed to update task:', error);
    }
  };

  // Mark task as completed
  const markAsCompleted = async (id) => {
    const taskToUpdate = tasks.find(task => task.id === id);
    const updatedTask = { ...taskToUpdate, completed: true };
    await updateTaskHandler(id, updatedTask);
  };

  // Delete a task
  const deleteTaskHandler = async (id) => {
    try {
      await deleteTask(id);
      setTasks(tasks.filter(task => task.id !== id));
    } catch (error) {
      console.error('Failed to delete task:', error);
    }
  };

  return (
    <Container>
      <Typography variant="h3" gutterBottom>
        Task Manager
      </Typography>
      <TaskForm onAddTask={addTask} />
      <Grid container spacing={4}>
        <Grid item xs={12} md={6}>
          <Typography variant="h5">Pending Tasks</Typography>
          <TaskList
            tasks={tasks.filter(task => !task.completed)}
            onMarkAsCompleted={markAsCompleted}
            onUpdateTask={updateTaskHandler}
            onDeleteTask={deleteTaskHandler}
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <Typography variant="h5">Completed Tasks</Typography>
          <CompletedTasks tasks={tasks.filter(task => task.completed)} />
        </Grid>
      </Grid>
    </Container>
  );
};

export default App;
